class TaskScheduler{
 constructor(limit=2){this.limit=limit;this.running=0;this.queue=[];}
 add(task,priority=0){
  return new Promise((resolve,reject)=>{
   this.queue.push({task,priority,resolve,reject});
   this.queue.sort((a,b)=>b.priority-a.priority);
   this.next();
  });
 }
 next(){
  while(this.running<this.limit&&this.queue.length){
   const item=this.queue.shift();this.running++;
   Promise.resolve().then(item.task).then(item.resolve,item.reject).finally(()=>{this.running--;this.next();});
  }
 }
}

class RateLimiter{
 constructor(capacity,interval){this.capacity=capacity;this.interval=interval;this.tokens=capacity;this.last=Date.now();this.queue=[];}
 async acquire(){
  while(true){
   const now=Date.now();
   this.tokens=Math.min(this.capacity,this.tokens+(now-this.last)*this.capacity/this.interval);
   this.last=now;
   if(this.tokens>=1){this.tokens--;return;}
   await new Promise(r=>setTimeout(r,Math.ceil(this.interval/this.capacity)));
  }
 }
}

