class CircuitBreaker{
 constructor(fn,{failureThreshold=3,resetTimeout=5000}={}){this.fn=fn;this.failureThreshold=failureThreshold;this.resetTimeout=resetTimeout;this.failures=0;this.state='CLOSED';}
 async call(...args){
  if(this.state==='OPEN'){if(Date.now()-this.openedAt<this.resetTimeout)throw new Error('Circuit open');this.state='HALF_OPEN';}
  try{const result=await this.fn(...args);this.failures=0;this.state='CLOSED';return result;}
  catch(e){this.failures++;if(this.failures>=this.failureThreshold){this.state='OPEN';this.openedAt=Date.now();}throw e;}
 }
}

function debounceAsync(fn,wait){
 let timer, pending=[];
 return (...args)=>new Promise((resolve,reject)=>{
  pending.push({resolve,reject});clearTimeout(timer);
  timer=setTimeout(async()=>{try{const value=await fn(...args);pending.splice(0).forEach(p=>p.resolve(value));}catch(e){pending.splice(0).forEach(p=>p.reject(e));}},wait);
 });
}

