class TimeoutMutex{
 constructor(){this.locked=false;this.queue=[];}
 acquire(timeout=5000){return new Promise((resolve,reject)=>{let timer;const grant=release=>{clearTimeout(timer);resolve(release);};if(!this.locked){this.locked=true;grant(()=>this.release());return;}this.queue.push(grant);timer=setTimeout(()=>{const i=this.queue.indexOf(grant);if(i>=0)this.queue.splice(i,1);reject(new Error('Lock timeout'));},timeout);});}
 release(){const next=this.queue.shift();if(next)next(()=>this.release());else this.locked=false;}
}

