class Container{
 constructor(){this.factories=new Map();this.cache=new Map();}
 register(token,factory,{singleton=false}={}){this.factories.set(token,{factory,singleton});}
 resolve(token){if(this.cache.has(token))return this.cache.get(token);const item=this.factories.get(token);if(!item)throw new Error(`Unknown dependency: ${String(token)}`);const value=item.factory(this);if(item.singleton)this.cache.set(token,value);return value;}
}

