function createStore(initial){
 let state=initial;const listeners=new Set();
 return {getState:()=>state,setState:update=>{const next=typeof update==='function'?update(state):update;const prev=state;state=next;for(const l of listeners)l(state,prev);},subscribe:fn=>{listeners.add(fn);return()=>listeners.delete(fn);}};
}

function createQueryCache(fetcher,staleTime=5000){
 const cache=new Map();const inFlight=new Map();
 return async key=>{
  const cached=cache.get(key);if(cached&&Date.now()-cached.time<staleTime)return cached.value;
  if(inFlight.has(key))return inFlight.get(key);
  const p=Promise.resolve().then(()=>fetcher(key)).then(value=>{cache.set(key,{value,time:Date.now()});return value;}).finally(()=>inFlight.delete(key));
  inFlight.set(key,p);return p;
 };
}

